{"content":"// Standalone verification of the gh-829 mergeStateLatch logic —
// replicates test_smGithubSource.js's gh-829 suite load()/wave.
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = '/home/runner/work/dmtools-agents/dmtools-agents';

function loadModule(file, requires, mocks) {
    const code = fs.readFileSync(path.join(ROOT, file), 'utf8');
    const sandbox = Object.assign({
        console, Date, JSON, Object, Array, String, Number, RegExp, parseInt, parseFloat, isNaN, Math,
        setTimeout, clearTimeout,
    }, mocks || {});
    sandbox.global = sandbox;
    vm.createContext(sandbox);
    const req = function (id) {
        if (requires && requires[id]) return requires[id];
        throw new Error('require not provided: ' + id);
    };
    vm.runInContext('(function(require, module, exports) {\n' + code + '\n})(__req__, __mod__, __mod__.exports)', vm.createContext(Object.assign(sandbox, { __req__: req, __mod__: { exports: {} } })));
    return sandbox.__mod__.exports;
}

const providerStub = {
    findPr: (n) => providerStub._prs[n] || null,
    prStatus: (n) => providerStub._status[n] || null,
    lastReview: () => null,
    reviewThreads: () => ({ total: 0, unresolved: 0 }),
    _prs: {}, _status: {},
};

function load(tools, prs, statuses, issueLabels, issueErrors) {
    providerStub._prs = prs || {};
    providerStub._status = statuses || {};
    const mergedTools = {
        github_get_issue: function (args) {
            const n = args && args.issueNumber;
            if (issueErrors && issueErrors[n]) return { message: 'Not Found' };
            const ls = (issueLabels && issueLabels[n]) || [];
            return { number: n, labels: ls.map((l) => ({ name: l })) };
        },
    };
    Object.keys(tools || {}).forEach((k) => { mergedTools[k] = tools[k]; });
    const machineAuthor = loadModule('js/common/machineAuthor.js', {}, {});
    const smAsync = loadModule('js/common/smAsync.js', { './common/smProvider.js': { createSmProvider: () => providerStub } }, mergedTools);
    return loadModule('js/sm/sources/githubSource.js', {
        '../../common/machineAuthor.js': machineAuthor,
        '../../common/smProvider.js': { createSmProvider: () => providerStub },
        '../../common/smAsync.js': smAsync,
    }, mergedTools);
}

const RULE = {
    source: 'github',
    query: {
        type: 'pr', checks: 'green',
        notLabels: ['ai_validating', 'pr_approved', 'ai_validated', 'chore:pin', 'validation_failed'],
        notMergeState: ['BEHIND', 'DIRTY'],
        mergeStateLatch: { CLEAN: ['ai_developed'] },
        draft: false,
    },
    localAction: 'validate_pr', skipIfGreenCi: true, limit: 1,
    id: 'validate-fresh-masked-green',
};

function pr(n, labels, mergeState, author) {
    return {
        number: n, labels: (labels || []).map((l) => ({ name: l })),
        draft: false, user: { login: author || 'ai-teammate' },
        head: { ref: 'ai/gh-' + (n - 1) }, body: 'Closes #' + (n - 1),
    };
}
const ISSUE_LABELS = { 825: ['ai_developed'], 835: ['ai_developed'], 837: ['ai_developed'], 839: ['ai_developed'], 841: ['ai_developed'] };

function wave() {
    return {
        github_list_prs: () => [
            pr(826), pr(827, [], 'CLEAN', 'vendor-guest'), pr(828),
            { number: 829, labels: [], draft: false, user: { login: 'ai-teammate' }, head: { ref: 'ai/gh-x' }, body: 'no anchor here' },
            pr(830, ['ai_validating']), pr(831, ['pr_approved']), pr(832, ['ai_validated']),
            pr(833, ['chore:pin']), pr(834, ['validation_failed']),
            pr(835, [], 'BLOCKED'), pr(836, [], 'BLOCKED'),
            pr(837, [], 'BEHIND'), pr(838, [], 'DIRTY'),
            { number: 840, labels: [], draft: true, user: { login: 'ai-teammate' }, head: { ref: 'wip' }, body: 'Closes #839' },
            { number: 842, labels: [], draft: false, user: { login: 'ai-teammate' }, head: { ref: 'ai/gh-841' }, body: 'Closes #841' },
        ],
    };
}
function statuses() {
    const s = {};
    [826, 827, 828, 829, 830, 831, 832, 833, 834, 835, 836, 837, 838, 840, 842]
        .forEach((n) => { s[n] = { number: n, state: 'OPEN', checks: 'green', mergeState: 'CLEAN', mergeable: true }; });
    s[835].mergeState = 'BLOCKED'; s[835].mergeable = false;
    s[836].mergeState = 'BLOCKED'; s[836].mergeable = false;
    s[837].mergeState = 'BEHIND'; s[837].mergeable = null;
    s[838].mergeState = 'DIRTY'; s[838].mergeable = null;
    s[842].checks = 'none';
    return s;
}

const src = load(wave(), {}, statuses(), ISSUE_LABELS, { 828: true });
const full = src.query(Object.assign({}, RULE, { limit: 50 }), { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
const keys = full.map((i) => i.key);
console.log('matched:', JSON.stringify(keys));
const expect = ['pr-826', 'pr-835', 'pr-836'];
console.log(keys.length === expect.length && keys.every((k, i) => k === expect[i]) ? '✅ AC1/AC2/AC3 matrix holds' : '❌ MISMATCH, expected ' + JSON.stringify(expect));

const one = src.query(RULE, { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
console.log('limit-1:', JSON.stringify(one.map((i) => i.key)), one[0] && one[0].key === 'pr-826' ? '✅ pacing' : '❌ pacing');

// BLOCKED branch without any github_get_issue at all
const src2 = load({
    github_list_prs: () => [pr(900, [], 'BLOCKED', 'vendor-guest'), pr(901, [], 'BLOCKED')],
}, {}, {
    900: { number: 900, state: 'OPEN', checks: 'green', mergeState: 'BLOCKED', mergeable: false },
    901: { number: 901, state: 'OPEN', checks: 'green', mergeState: 'BLOCKED', mergeable: false },
});
const items2 = src2.query(Object.assign({}, RULE, { limit: 10 }), { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
console.log('BLOCKED-no-fetch:', JSON.stringify(items2.map((i) => i.key)),
    items2.length === 2 ? '✅ gh-757 contract intact' : '❌ BLOCKED branch regressed');

// Old (pre-gh-829) query must NOT match pr-826
const oldRule = {
    source: 'github',
    query: { type: 'pr', checks: 'green', notLabels: RULE.query.notLabels.slice(), notMergeState: ['BEHIND', 'DIRTY', 'CLEAN'], draft: false },
    localAction: 'validate_pr', skipIfGreenCi: true, limit: 50, id: 'validate-fresh-masked-green',
};
const src3 = load(wave(), {}, statuses(), ISSUE_LABELS, { 828: true });
const oldItems = src3.query(oldRule, { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
console.log('old-query matches pr-826?', oldItems.map((i) => i.key).indexOf('pr-826') !== -1 ? '❌' : '✅ (dead zone reproduced)');

// String-form latch robustness probe: {"CLEAN": "ai_developed"} (not in deployed config)
const strRule = Object.assign({}, RULE, { query: Object.assign({}, RULE.query, { mergeStateLatch: { CLEAN: 'ai_developed' } }) });
const src4 = load(wave(), {}, statuses(), ISSUE_LABELS, { 828: true });
const strItems = src4.query(Object.assign({}, strRule, { limit: 50 }), { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
console.log('string-latch matches:', JSON.stringify(strItems.map((i) => i.key)));

// pr-less item with latch-only rule (no notMergeState): does it pass the latch?
const latchOnlyRule = {
    source: 'github',
    query: { type: 'pr', checks: 'green', mergeStateLatch: { CLEAN: ['ai_developed'] } },
    localAction: 'x', limit: 50, id: 'probe',
};
const src5 = load({
    github_list_prs: () => [{ number: 950, labels: [], draft: false, user: { login: 'ai-teammate' }, head: { ref: 'x' }, body: 'Closes #941' }],
}, {}, { 950: { number: 950, state: 'OPEN', checks: 'green', mergeable: null } }, { 941: ['ai_developed'] });
const items5 = src5.query(latchOnlyRule, { repoInfo: { owner: 'IstiN', repo: 'x' } });
console.log('pr-less item passes latch-only rule?', items5.length > 0 ? 'YES (guard skips when item.pr missing)' : 'no');
