const oldItems = src3.query(oldRule, { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
console.log('old-query matches pr-826?', oldItems.map((i) => i.key).indexOf('pr-826') !== -1 ? '❌' : '✅ (dead zone reproduced)');

// String-form latch robustness probe: {"CLEAN": "ai_developed"} (not in deployed config)
const strRule = Object.assign({}, RULE, { query: Object.assign({}, RULE.query, { mergeStateLatch: { CLEAN: 'ai_developed' } }) });
const src4 = load(wave(), {}, statuses(), ISSUE_LABELS, { 828: true });
const strItems = src4.query(Object.assign({}, strRule, { limit: 50 }), { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
console.log('string-latch matches:', JSON.stringify(strItems.map((i) => i.key)));

// pr-less item with latch-only rule (no notMergeState): does it pass the latch?
const latchOnlyRule = {
    source: 'github',
